import {hardware,hardwareById,hardwareApplications,hardwareFor,filterHardware,resourcePhoto,hardwareTypesFor,hardwareTypeByPath,resourceMediaForNode} from './resource-catalog.mjs';
export function createHardwareUI({esc,btn,crumb}){
 const finishStyle=f=>{const hex=/^#[a-f\d]{3,8}$/i.test(f.hex||'')?f.hex:'#bfc3c4';return `--finish-color:${hex}`;};
 const swatches=(item,selected='')=>`<div class="hardware-swatches" aria-label="Доступные отделки">${item.finishes.map(f=>`<span class="finish-swatch ${selected===f.id?'is-selected':''}" style="${finishStyle(f)}" title="${esc(f.label)}" aria-label="${esc(f.label)}"></span>`).join('')}</div>`;
 function card(item,finish=''){const media=resourceMediaForNode(item,{finish});return `<a class="choice-card hardware-card" href="${item.url}${finish?'?finish='+encodeURIComponent(finish):''}"><div class="choice-photo">${resourcePhoto(item,{finish})}${item.brand==='Pauli'?'<span class="hardware-brand">Pauli</span>':''}</div><div class="choice-copy"><span class="eyebrow">${esc(item.typeLabel)}</span><h3>${esc(item.title)}</h3>${swatches(item,finish)}<p>${esc(item.intro)}</p>${media.limitation?`<p class="resource-media-caption">${esc(media.limitation)}</p>`:''}<div class="choice-bottom"><span>${item.finishes.length} ${item.finishes.length===1?'отделка':'отделок'} для выбора</span><span class="choice-arrow">→</span></div></div></a>`;}
 function entry(category){if(category==='mirrors')return '';const app=hardwareApplications.find(a=>a.id===category);if(!app)return '';return `<section class="hardware-context"><div><span class="eyebrow">КОМПЛЕКТАЦИЯ КОНСТРУКЦИИ</span><h2>Фурнитура.<br><em>Важная часть решения.</em></h2><p>Выберите вид и отделку элементов ${category==='showers'?'душевой':category==='stairs'?'ограждения':'конструкции'}.</p>${btn('Выбрать фурнитуру','#/hardware/'+category,'clear')}</div><a href="#/hardware/${category}" aria-label="${esc(app.title)} — фурнитура">${resourcePhoto(app)}</a></section>`;}
 function picker(category){if(category==='mirrors')return '';const list=hardwareFor(category);if(!list.length)return '';return `<fieldset class="hardware-picker"><legend>Фурнитура конструкции</legend><p>Выберите основной элемент и отделку. Остальные детали можно указать в пожеланиях.</p><div class="form-grid"><div class="field full"><label for="hardware-item">Вид фурнитуры</label><select id="hardware-item" name="hardware-item" data-hardware-select><option value="">Подобрать вместе с конструкцией</option>${list.map(x=>`<option value="${x.id}">${esc(x.title)}${x.brand==='Pauli'?' · Pauli':''}</option>`).join('')}</select></div><div class="field full"><label for="hardware-finish">Отделка фурнитуры</label><select id="hardware-finish" name="hardware-finish" disabled><option value="">Сначала выберите вид</option></select></div></div><a class="hardware-catalog-link" href="#/hardware/${category}" target="_blank" rel="noopener">Посмотреть варианты с изображениями ↗</a></fieldset>`;}
 function select(label,name,options,selected){return `<label>${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
 function home(){return `${crumb([['Фурнитура']])}<section class="selection-page"><header class="selection-heading"><span class="eyebrow">В СОСТАВЕ НАШИХ КОНСТРУКЦИЙ</span><h1>Детали, которые<br><em>собирают целое.</em></h1><p>Каталог для выбора вида и отделки фурнитуры в вашем изделии. Отдельно фурнитуру не продаём.</p></header><div class="choice-grid">${hardwareApplications.map(a=>`<a class="choice-card" href="#/hardware/${a.id}"><div class="choice-photo">${resourcePhoto(a)}</div><div class="choice-copy"><h3>${esc(a.title)}</h3><p>${esc(a.intro)}</p><div class="choice-bottom"><span>Виды и отделки</span><span class="choice-arrow">→</span></div></div></a>`).join('')}</div></section>`;}
 function typeCard(node){const media=resourceMediaForNode(node);return `<a class="choice-card hardware-type-card" href="${node.url}" data-hardware-type="${node.path}"><div class="choice-photo">${resourcePhoto(node)}</div><div class="choice-copy"><h3>${esc(node.title)}</h3><div class="card-subtypes">${node.children.map(x=>`<span>${esc(x.title)}</span>`).join('')}</div>${media.limitation?`<p class="resource-media-caption">${esc(media.limitation)}</p>`:''}<div class="choice-bottom"><span>${node.children.length} отдельных вариантов</span><span class="choice-arrow">→</span></div></div></a>`;}
 function listing(category,params,type=''){
  if(category==='mirrors')return null;
  const app=hardwareApplications.find(a=>a.id===category),typeNode=type?hardwareTypeByPath.get('/hardware/'+category+'/'+type):null;if(!app||type&&!typeNode)return null;
  const selected=new URLSearchParams(params);if(type)selected.set('type',type);
  const all=hardwareFor(category),list=filterHardware(category,selected),typePages=hardwareTypesFor(category),types=typePages.map(x=>[x.type,x.title]);
  const finishes=[...new Map((typeNode?.children||all).flatMap(x=>x.finishes.map(f=>[f.id,f.label]))).entries()];
  const hasFilter=['type','finish','q'].some(k=>params.get(k)),showTypes=!type&&!hasFilter;
  const empty=`<div class="empty"><h3>Нет такого сочетания</h3><p>Измените вид или отделку — доступные цвета различаются по моделям.</p>${btn('Сбросить выбор',typeNode?.url||'#/hardware/'+category,'clear')}</div>`;
  return `${crumb([['Фурнитура','#/hardware'],[app.title,type?'#/hardware/'+category:null],...(type?[[typeNode.title]]:[])])}<section class="selection-page"><nav class="selection-toolbar"><a class="selection-back" href="${type?'#/hardware/'+category:'#/catalog/'+category}">← ${type?'Все виды фурнитуры':esc(app.title.replace(/^Для /,''))}</a><a class="selection-map" href="#/hardware">Вся фурнитура ↗</a></nav><header class="selection-heading"><span class="eyebrow">КОМПЛЕКТАЦИЯ / ОТДЕЛЬНЫЕ ВИДЫ</span><h1>${type?esc(typeNode.title)+'<br><em>'+esc(app.title.toLowerCase())+'</em>':'Фурнитура<br><em>'+esc(app.title.toLowerCase())+'.</em>'}</h1><p>${type?esc(typeNode.intro):esc(app.intro)} Только в составе конструкции, без отдельной продажи.</p></header><form class="resource-filter-form hardware-filter" id="hardware-filter-form" data-category="${category}" data-type="${esc(type)}">${type?`<input type="hidden" name="type" value="${esc(type)}">`:select('Вид элемента','type',[['','Все виды'],...types],params.get('type')||'')}${select('Цвет и поверхность','finish',[['','Все отделки'],...finishes],params.get('finish')||'')}<label>Поиск<input name="q" type="search" value="${esc(params.get('q')||'')}" placeholder="Например, ручка"></label><button type="submit" class="btn primary">Показать <span>→</span></button><a class="filter-clear" href="${typeNode?.url||'#/hardware/'+category}">Сбросить</a></form><p class="resource-result-count">${showTypes?typePages.length+' самостоятельных видов фурнитуры':list.length+' вариантов комплектации'}</p><div class="choice-grid">${showTypes?typePages.map(typeCard).join(''):list.length?list.map(x=>card(x,params.get('finish'))).join(''):empty}</div>${type?`<section class="hardware-type-directory"><div class="section-top"><h2>Другие виды фурнитуры</h2></div><div class="directory-subtypes">${typePages.filter(x=>x.type!==type).map(typeCard).join('')}</div></section>`:''}<div class="selection-footer"><p>Фурнитуру подбираем с учётом стекла, размеров и схемы установки.</p>${btn('Выбрать конструкцию','#/catalog/'+category,'clear')}</div></section>`;
 }
 function detail(item,params,projectItems=[]){
  if(!item||!item.applications?.some(category=>category!=='mirrors'))return null;
  const selected=item.finishes.some(f=>f.id===params.get('finish'))?params.get('finish'):item.finishes[0]?.id||'';
  const media=resourceMediaForNode(item,{finish:selected});
  const eligible=projectItems.filter(p=>p.catalogPath&&item.applications.includes(p.catalogPath.split('/')[2]));
  return `${crumb([['Фурнитура','#/hardware'],[hardwareApplications.find(x=>x.id===item.applications[0])?.title||'Комплектация','#/hardware/'+item.applications[0]],[item.typeLabel,'#/hardware/'+item.applications[0]+'/'+item.type],[item.title]])}<section class="selection-page selected-product hardware-detail"><nav class="selection-toolbar"><a class="selection-back" href="#/hardware/${item.applications[0]}/${item.type}">← ${esc(item.typeLabel)}</a><a class="selection-map" href="#/project">Мой проект ↗</a></nav><div class="leaf-layout"><div class="leaf-visual"><figure class="product-gallery"><button type="button" class="gallery-open" data-resource-src="${esc(media.src)}" data-resource-alt="${esc(media.alt)}" data-caption="${esc(media.caption)}">${resourcePhoto(item,{eager:true,finish:selected})}<span class="gallery-expand">↗</span></button><p data-hardware-caption>${esc(media.caption)}</p><figcaption><span>${esc(item.typeLabel)}</span><span>Увеличить ↗</span></figcaption></figure></div><div class="leaf-details"><span class="eyebrow">КОМПЛЕКТАЦИЯ КОНСТРУКЦИИ${item.brand==='Pauli'?' / PAULI':''}</span><h1>${esc(item.title)}</h1><p>${esc(item.intro)}</p><form id="hardware-choice-form" class="config-form hardware-order" data-hardware="${item.id}"><fieldset class="finish-fieldset"><legend>Цвет и поверхность</legend><div class="finish-options">${item.finishes.map(f=>`<label class="finish-choice"><input type="radio" name="finish" value="${f.id}" ${f.id===selected?'checked':''}><span class="finish-swatch" style="${finishStyle(f)}"></span><span>${esc(f.label)}</span></label>`).join('')}</div></fieldset><div class="field"><label for="hardware-target">Добавить к конструкции</label><select id="hardware-target" name="target"><option value="">Сохранить пожелание к проекту</option>${eligible.map(p=>`<option value="${esc(p.uid)}">${esc(p.title)}</option>`).join('')}</select></div><div class="field"><label for="hardware-note">Пожелание</label><textarea id="hardware-note" name="note" placeholder="Где использовать этот элемент, что важно учесть…"></textarea></div><button class="btn primary" type="submit">Сохранить выбор в проекте <span>+</span></button><div id="hardware-added" class="added-confirmation" hidden><span>Выбор сохранён.</span><a href="#/project">Открыть проект →</a></div><p class="form-note">Фурнитура комплектуется вместе с изделием. Отдельный заказ фурнитуры не оформляется.</p></form>${item.notes?.length?`<details class="choice-help"><summary>Что учесть при подборе</summary><div class="choice-help-body">${item.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div></details>`:''}</div></div><section class="resource-related"><div class="section-top"><h2>Для каких конструкций</h2></div><div class="hardware-application-links">${item.applications.map(id=>{const a=hardwareApplications.find(x=>x.id===id);return a?btn(a.title,'#/catalog/'+id,'clear'):''}).join('')}</div></section></section>`;
 }
 function updateFinishPreview(form){
  if(!form)return;
  const item=hardwareById.get(form.dataset.hardware);if(!item)return;
  const finish=form.querySelector('input[name="finish"]:checked')?.value||'';
  const media=resourceMediaForNode(item,{finish});
  const gallery=form.closest('.hardware-detail')?.querySelector('.product-gallery');if(!gallery)return;
  const button=gallery.querySelector('.gallery-open'),caption=gallery.querySelector('[data-hardware-caption]');
  if(button){button.innerHTML=resourcePhoto(item,{eager:true,finish})+'<span class="gallery-expand">↗</span>';button.dataset.resourceSrc=media.src;button.dataset.resourceAlt=media.alt;button.dataset.caption=media.caption;}
  if(caption)caption.textContent=media.caption;
 }
 return {home,listing,detail,entry,picker,card,typeCard,updateFinishPreview};
}
